+import { type NextRequest } from "next/server";
+import { getUser } from "@/lib/auth";
+import { createClient } from "@/lib/supabase/server";
+import {
+  getBooking,
+  getSessionByBooking,
+  getApprovedProvider,
+} from "@/lib/db/queries";
+import { formatCents } from "@/lib/format";
+import { durationLabel } from "@/lib/time";
+import { t } from "@/lib/i18n";
+
+/**
+ * Downloadable plain-text receipt for a completed booking. Returns an
+ * attachment; the booking must belong to the caller (RLS-enforced read).
+ */
+export async function GET(
+  _req: NextRequest,
+  ctx: { params: Promise<{ bookingId: string }> },
+) {
+  const user = await getUser();
+  if (!user) {
+    return new Response(t("receipt.notFound"), { status: 401 });
+  }
+  const { bookingId } = await ctx.params;
+  const [booking, session] = await Promise.all([
+    getBooking(bookingId),
+    getSessionByBooking(bookingId),
+  ]);
+  if (!booking || booking.customer_id !== user.id || !session) {
+    return new Response(t("receipt.notFound"), { status: 404 });
+  }
+
+  const provider = await getApprovedProvider(booking.provider_id);
+  const supabase = await createClient();
+  const { data: payment } = await supabase
+    .from("payments")
+    .select("payment_ref, status")
+    .eq("booking_id", bookingId)
+    .maybeSingle();
+
+  const lines = [
+    t("receipt.heading"),
+    "",
+    `${t("receipt.booking")}: ${booking.id}`,
+    `${t("receipt.listener")}: ${provider?.display_name ?? "—"}`,
+    `${t("receipt.date")}: ${session.ended_at ?? "—"}`,
+    `${t("receipt.duration")}: ${durationLabel(session.elapsed_seconds)}`,
+    `${t("receipt.block")}: ${t("receipt.minutes", { minutes: session.block_minutes })}`,
+    session.overage_minutes > 0
+      ? `${t("receipt.overage")}: ${t("receipt.minutes", { minutes: session.overage_minutes })}`
+      : null,
+    `${t("receipt.total")}: ${formatCents(session.total_price_cents)}`,
+    `${t("receipt.payment")}: ${payment?.payment_ref ?? "—"} (${payment?.status ?? "—"})`,
+    "",
+    t("receipt.footer"),
+    "",
+  ]
+    .filter((l) => l !== null)
+    .join("\n");
+
+  return new Response(lines, {
+    status: 200,
+    headers: {
+      "Content-Type": "text/plain; charset=utf-8",
+      "Content-Disposition": `attachment; filename="heard-receipt-${booking.id.slice(0, 8)}.txt"`,
+    },
+  });
+}

