import { notFound, redirect } from "next/navigation";
import { SessionFlow } from "@/components/session/SessionFlow";
import { requireRole } from "@/lib/auth";
import { getBooking, getApprovedProvider } from "@/lib/db/queries";

export default async function SessionPage({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  await requireRole("customer");
  const { id } = await params;
  const booking = await getBooking(id);
  if (!booking) notFound();
  if (booking.status === "completed") redirect(`/session/${id}/summary`);

  const provider = await getApprovedProvider(booking.provider_id);
  if (!provider) notFound();

  return (
    <SessionFlow
      bookingId={id}
      name={provider.display_name}
      avatarColor={provider.avatar_color}
    />
  );
}

